byte E2E_1D_ID_CRC8(byte da[],byte bytelbit[],int dataLength,word dataId)
{
  byte byte_index=0,bit_index=0,byte_i = 0;
  byte CRC=0;
  byte POLY;
  byte b=0;
  byte_index=0;
  bit_index=0;
  CRC=0xFF;
  POLY=0x1d;

  // 校验数组 = DataID 低字节、高字节（小端序）+ 原校验数组
  for(byte_index=0;byte_index<dataLength+2;byte_index++)
  {
    if(byte_index==0)
    {
      b=(byte)(dataId & 0xFF);
    }
    else if(byte_index==1)
    {
      b=(byte)((dataId >> 8) & 0xFF);
    }
    else
    {
      b=da[byte_index-2];
      for ( byte_i = 0; byte_i < elcount(bytelbit); byte_i++)
      {
        if(bytelbit[byte_i]==byte_index-2)
         { break;}
      }
      if(byte_i<elcount(bytelbit))
      {
        continue;
      }
    }
    CRC ^=b;

    for( bit_index=0; bit_index<8; ++bit_index )
    {
      if( (CRC & 0x80) > 0 )
      {
        CRC = (CRC << 1) ^ POLY;
      }
      else
        CRC = (CRC << 1);
    }
  }
  CRC^=0xFF;
  return CRC;
  }

